mapper.select:
/* isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper - selectMenteeList */ /* Lee SangHoon [멘티목록조회(멘토멘티매칭용)] */
SELECT
A.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ ,A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ ,A.CASE_MNG_NO || '-' || A.CASE_MNG_ODRNO AS MENTEE_NO /* 멘티번호[사례관리번호-차수] */ ,DEC_B64(B.TRPR_NM_ENCPT) AS MENTEE_NM /* 멘티명(암호화) */ ,C.SCHL_NM AS MENTEE_SCHL_NM /* 학교명 */ ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드값 */ WHERE CMMNS_CD_ID = 'GRADE_SE_CD' AND CMMNS_CD_VALUE = C.GRADE_SE_CD) AS MENTEE_GRADE /* 학년 */
,D.SRVC_EXCN_BIZ_NO AS SRVC_EXCN_BIZ_NO /* 서비스실행사업번호 */ ,A.ALTMNT_GROUP_SCLAS_SE_CD AS ALTMNT_GROUP_SCLAS_SE_CD /* 배정그룹소분류구분코드 */
FROM SEB100 A /* 사례기본 */ JOIN SEA200 B /* 대상자정보 */ ON B.TRPR_INFO_NO = A.TRPR_INFO_NO LEFT JOIN (SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN FROM SEA230 A /* 학력상태 */ LEFT JOIN SAC100 B ON B.CMMNS_CD_ID = 'ACBG_SE_CD' AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD WHERE A.DEL_YN != 'Y' ) C ON C.TRPR_INFO_NO = A.TRPR_INFO_NO AND C.RN = 1 INNER JOIN SEB120 D /* 서비스사업대상자 */ ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO INNER JOIN SDA420 E /* 서비스실행사업 */ ON E.SRVC_EXCN_BIZ_NO = D.SRVC_EXCN_BIZ_NO
WHERE 1=1 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND (E.INST_NO = #{INST_NO} OR #{INST_TYPE_SE_CD} IN('1','4','6'))
AND D.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
AND A.ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}
ORDER BY A.CASE_MNG_NO, A.CASE_MNG_ODRNO

/* isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper.selectMmMatchingList */ /* 멘토멘티매칭 목록조회 - Lee SangHoon */
SELECT A.MENTOR_NO AS MENTOR_NO /* 멘토번호(종사자번호) */ , DEC_B64(B.FLNM_ENCPT) AS MENTOR_NM /* 멘토명[암호화] */ , C.SCHL_NM AS MENTOR_SCHL_NM /* 멘토학교명 */ , C.MAJOR_NM AS MENTOR_MAJOR_NM /* 멘토전공명 */ , A.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , A.CASE_MNG_NO || '-' || A.CASE_MNG_ODRNO AS MENTEE_NO /* 멘티번호[사례관리번호-차수] */ , DEC_B64(E.TRPR_NM_ENCPT) AS MENTEE_NM /* 멘티명(암호화) */ , E.TRPR_BRTH_YMD AS BRDT /* 대상자출생일자(멘티) */ , E.SXDC_SE_CD AS SXDC_SE_CD /* 성별구분코드(멘티) */ , F.SCHL_NM AS MENTEE_SCHL_NM /* 멘티학교명 */ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'ACBG_SE_CD' AND CMMNS_CD_VALUE = F.ACBG_SE_CD) AS SCHL /* 교급(멘티) */ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'GRADE_SE_CD' AND CMMNS_CD_VALUE = F.GRADE_SE_CD) AS MENTEE_GRADE /* 멘티학년 */ , A.RM_NM AS RM_NM /* 비고명 */ , A.SRVC_EXCN_BIZ_NO AS SRVC_EXCN_BIZ_NO /* 서비스실행사업번호 */ , A.ALTMNT_GROUP_SCLAS_SE_CD AS ALTMNT_GROUP_SCLAS_SE_CD /* 배정그룹구분코드 */ , G.GNRLZ_OPIN_DTL_CN AS GNRLZ_OPIN_DTL_CN /* 종합소견상세내용 */ FROM AFA250 A /* 멘토멘티매칭 */ JOIN SCA100 B /* 종사자 */ ON B.ENFSN_NO = A.MENTOR_NO LEFT JOIN (SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.ENFSN_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN FROM SCA120 A /* 학력사항정보 */ LEFT JOIN SAC100 B ON B.CMMNS_CD_ID = 'ACBG_SE_CD' AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD WHERE A.DEL_YN != 'Y' ) C ON C.ENFSN_NO = B.ENFSN_NO AND C.RN = 1 JOIN SEB100 D /* 사례기본 */ ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEA200 E /* 대상자정보 */ ON E.TRPR_INFO_NO = D.TRPR_INFO_NO LEFT JOIN (SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN FROM SEA230 A /* 학력상태 */ LEFT JOIN SAC100 B ON B.CMMNS_CD_ID = 'ACBG_SE_CD' AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD WHERE A.DEL_YN != 'Y' ) F ON F.TRPR_INFO_NO = E.TRPR_INFO_NO AND F.RN = 1 LEFT JOIN AFA260 G /* 멘토관찰일지 */ ON G.SRVC_EXCN_BIZ_NO = A.SRVC_EXCN_BIZ_NO AND G.CASE_MNG_NO = A.CASE_MNG_NO AND G.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO
WHERE 1=1
AND A.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
AND A.ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}
ORDER BY CASE_MNG_NO, CASE_MNG_ODRNO

mapper.insert:

