    ,#{ALTMNT_GROUP_SCLAS_SE_CD}
    ,#{MENTOR_NO}
    ,#{CASE_MNG_NO}
    ,#{CASE_MNG_ODRNO}
    ,#{RM_NM}
    ,#{LGN_USER_ID}
    ,#{LGN_USER_ID}
)

mapper.update:

/* 멘토멘티매칭 수정 - Lee SangHoon [isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper.updateMmMatchingList] */

UPDATE AFA250 SET   /* 멘토멘티매칭 */
    SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
    ,ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}
    ,MENTOR_NO = #{MENTOR_NO}
    ,CASE_MNG_NO = #{CASE_MNG_NO}
    ,CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
    ,RM_NM = #{RM_NM}
    ,FRST_RGTR_ID = #{LGN_USER_ID}
    ,LAST_MDFR_ID = #{LGN_USER_ID}
    ,LAST_MDFCN_DT = SYSDATE
WHERE SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO__origin}
AND ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD__origin}
AND MENTOR_NO = #{MENTOR_NO__origin}
AND CASE_MNG_NO = #{CASE_MNG_NO__origin}
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO__origin}

mapper.delete:

    /* 멘토멘티매칭 삭제 - Lee SangHoon [isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper.deleteMmMatchingList] */

	DELETE FROM AFA250     /* 멘토멘티매칭 */
    WHERE SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO__origin}
    AND ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD__origin}
    AND MENTOR_NO = #{MENTOR_NO__origin}
    AND CASE_MNG_NO = #{CASE_MNG_NO__origin}
    AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO__origin}

mapper.select:
/* isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper.selectDayObservDiaryList */ /* 일일관찰일지 목록조회 - Lee Sanghoon */ B.WRT_YMD AS CHCK_YMD --점검일자 , B.DD_ODRNO --일차 , DEC_B64(D.TRPR_NM_ENCPT) AS TRPR_NM --대상자명(암호화) , NVL(G.BRTH_YMD, D.TRPR_BRTH_YMD) AS BRDT --생년월일 , TRUNC(MONTHS_BETWEEN (SYSDATE,NVL(G.BRTH_YMD, D.TRPR_BRTH_YMD)) /12,0) AS AGEA --만 나이 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(G.SXDC_SE_CD, D.SXDC_SE_CD) ) AS SXDC_SE_CD --성별 , E.SCHL_NM --학교명 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'GRADE_SE_CD' AND CMMNS_CD_VALUE = E.GRADE_SE_CD ) AS GRADE --학년명 , H.SRVC_EXCN_BIZ_NM AS CRSE_NM --과정명(서비스실행사업명) , A.ALTMNT_GROUP_SCLAS_SE_CD --생활동(배정그룹소분류구분코드) , DEC_B64(F.FLNM_ENCPT) AS WRTR_NM --작성자명(암호화) , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SNITAT_STTS_SE_CD' AND CMMNS_CD_VALUE = B.SNITAT_STTS_SE_CD ) AS SNITAT_STTS_SE_CD --위생상태 , (SELECT CMMNS_cD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'HEALTH_SE_CD' AND CMMNS_CD_VALUE = B.HEALTH_SE_CD ) AS HEALTH_SE_CD --건강상태 , CASE WHEN (A.GNRLZ_OPIN_DTL_CN IS NULL OR A.GNRLZ_OPIN_DTL_CN = '') THEN 'X' ELSE 'O' END AS GNRLZ_OPIN_YN --종합소견여부 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'PTCPTN_ATITD_SE_CD' AND CMMNS_CD_VALUE = B.PTCPTN_ATITD_SE_CD ) AS PTCPTN_ATITD_SE_CD --참여태도구분코드 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'GHVR_CHAR_SE_CD' AND CMMNS_CD_VALUE = B.GHVR_CHAR_SE_CD ) AS GHVR_CHAR_SE_CD --행동특성구분 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'LEADER_TWDPSN_REL_SE_CD' AND CMMNS_CD_VALUE = B.LEADER_TWDPSN_REL_SE_CD ) AS LEADER_TWDPSN_REL_SE_CD --지도자와의대인관계 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'FRIDA_TWDPSN_REL_SE_CD' AND CMMNS_CD_VALUE = B.FRIDA_TWDPSN_REL_SE_CD ) AS FRIDA_TWDPSN_REL_SE_CD --또래와의대인관계구분명 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'GOAL_ACHIV_DGREE_SE_CD' AND CMMNS_CD_VALUE = B.GOAL_ACHIV_DGREE_SE_CD ) AS GOAL_ACHIV_DGREE_SE_CD --개별목표달성정도
, A.SRVC_EXCN_BIZ_NO --서비스실행사업번호 , A.CASE_MNG_NO || '-' || A.CASE_MNG_ODRNO AS MENTEE_NO -- 멘티번호[사례관리번호-차수] , B.WRT_YMD --작성일자
FROM AFA260 A /*멘토관찰일지 테이블*/ INNER JOIN AFA261 B /*멘토관찰일지상세내용 테이블*/ ON A.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO --서비스실행사업번호 AND A.CASE_MNG_NO = B.CASE_MNG_NO --사례관리번호 AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO --사례관리차수 LEFT JOIN SEB100 C /*사례기본 테이블*/ ON A.CASE_MNG_NO = C.CASE_MNG_NO --사례관리번호 AND A.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO --사례관리차수 LEFT JOIN SEA200 D /*대상자정보 테이블*/ ON C.TRPR_INFO_NO = D.TRPR_INFO_NO --대상자정보번호 LEFT JOIN (SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN FROM SEA230 A LEFT JOIN SAC100 B ON B.CMMNS_CD_ID = 'ACBG_SE_CD' AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD WHERE A.DEL_YN != 'Y' ) E /*학력관리 테이블*/ ON E.RN = 1 AND D.TRPR_INFO_NO = E.TRPR_INFO_NO --대상자정보번호 LEFT JOIN SCA100 F /*종사자 테이블*/ ON B.PIC_NO = F.ENFSN_NO --종사자번호 LEFT JOIN SDA420 H /*서비스실행사업 테이블*/ ON A.SRVC_EXCN_BIZ_NO = H.SRVC_EXCN_BIZ_NO --서비스실행사업번호 LEFT JOIN SCA300 G /* 대상자 개인정보 */ ON G.INDV_IDNTFC_NO = D.INDV_IDNTFC_NO -- 개인식별번호
WHERE 1=1 AND (B.TKCG_INST_NO = #{INST_NO} OR #{INST_TYPE_SE_CD} IN ('1','4','6'))
AND A.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
AND A.ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}
AND B.PIC_NO = #{ENFSN_NO}
AND A.CASE_MNG_NO = #{CASE_MNG_NO}
AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
AND B.WRT_YMD BETWEEN #{BGNG_YMD} AND #{END_YMD}
ORDER BY B.WRT_YMD DESC, A.CASE_MNG_NO, A.CASE_MNG_ODRNO

