    /* isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper.insertDayObservDiaryDtl */
    /* 멘토관찰일지상세내용 등록 - Lee Sanghoon */

	INSERT INTO AFA261(

		SRVC_EXCN_BIZ_NO                      --서비스실행사업번호
		,CASE_MNG_NO                          --사례관리번호
		,CASE_MNG_ODRNO                       --사례관리차수
		,WRT_YMD                              --작성일자
