		,HEALTH_SE_CD                         --건강구분코드
		,HEALTH_PRTCLR_MATTER_NM              --건강특이사항명
		,PTCPTN_ATITD_SE_CD                   --참여태도구분코드
		,PTCPTN_ATITD_ETC_NM                  --참여태도기타명
		,GHVR_CHAR_SE_CD                      --행동특성구분코드
		,MAOB_EXPRSN_NM                       --주관찰표현명
		,LEADER_TWDPSN_REL_SE_CD              --지도자와의대인관계구분코드
		,LEADER_REL_ETC_NM                    --지도자관계기타명
		,FRIDA_TWDPSN_REL_SE_CD               --또래와의대인관계구분코드
		,FRIDA_REL_ETC_NM                     --또래관계기타명
		,GOAL_ACHIV_DGREE_SE_CD               --목표달성정도구분코드
		,INDIV_GOAL_ETC_NM                    --개별목표기타명
		,POSTV_SIDE_CN                        --긍정측면내용
		,DD_DD_OPIN_CN                        --일일소견내용
		,PIC_NO                               --담당자번호
		,TKCG_INST_NO                         --담당기관번호
		,FRST_RGTR_ID                         --최초등록자아이디
		,LAST_MDFR_ID                         --최종수정자아이디

	) VALUES(

