		,#{PTCPTN_ATITD_ETC_NM}
		,#{GHVR_CHAR_SE_CD}
		,#{MAOB_EXPRSN_NM}
		,#{LEADER_TWDPSN_REL_SE_CD}
		,#{LEADER_REL_ETC_NM}
		,#{FRIDA_TWDPSN_REL_SE_CD}
		,#{FRIDA_REL_ETC_NM}
		,#{GOAL_ACHIV_DGREE_SE_CD}
		,#{INDIV_GOAL_ETC_NM}
		,#{POSTV_SIDE_CN}
		,#{DD_DD_OPIN_CN}
		,#{ENFSN_NO}
		,#{TKCG_INST_NO}
		,#{LGN_USER_ID}
