	)

mapper.update:

    /* isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper.updateDayObservDiary */
    /* 멘토관찰일지 수정 - Lee Sanghoon */

	UPDATE AFA260 SET

		GNRLZ_OPIN_DTL_CN = #{GNRLZ_OPIN_DTL_CN}
		,LAST_MDFR_ID = #{LGN_USER_ID}
		,LAST_MDFCN_DT = SYSDATE

	WHERE SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
	AND CASE_MNG_NO = #{CASE_MNG_NO}
