/* isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper.updateDayObservDiaryDtl */ /* 멘토관찰일지상세내용 수정 - Lee Sanghoon */
UPDATE AFA261 SET
WRT_YMD = #{WRT_YMD} --작성일자 ,DD_ODRNO = #{DD_ODRNO} --일차 ,SNITAT_STTS_SE_CD = #{SNITAT_STTS_SE_CD} --위생상태구분코드 ,SNITAT_ETC_NM = #{SNITAT_ETC_NM} --위생기타명 ,HEALTH_SE_CD = #{HEALTH_SE_CD} --건강구분코드 ,HEALTH_PRTCLR_MATTER_NM = #{HEALTH_PRTCLR_MATTER_NM} --건강특이사항명 ,PTCPTN_ATITD_SE_CD = #{PTCPTN_ATITD_SE_CD} --참여태도구분코드 ,PTCPTN_ATITD_ETC_NM = #{PTCPTN_ATITD_ETC_NM} --참여태도기타명 ,GHVR_CHAR_SE_CD = #{GHVR_CHAR_SE_CD} --행동특성구분코드 ,MAOB_EXPRSN_NM = #{MAOB_EXPRSN_NM} --주관찰표현명 ,LEADER_TWDPSN_REL_SE_CD = #{LEADER_TWDPSN_REL_SE_CD} --지도자와의대인관계구분코드 ,LEADER_REL_ETC_NM = #{LEADER_REL_ETC_NM} --지도자관계기타명 ,FRIDA_TWDPSN_REL_SE_CD = #{FRIDA_TWDPSN_REL_SE_CD} --또래와의대인관계구분코드 ,FRIDA_REL_ETC_NM = #{FRIDA_REL_ETC_NM} --또래관계기타명 ,GOAL_ACHIV_DGREE_SE_CD = #{GOAL_ACHIV_DGREE_SE_CD} --목표달성정도구분코드 ,INDIV_GOAL_ETC_NM = #{INDIV_GOAL_ETC_NM} --개별목표기타명 ,POSTV_SIDE_CN = #{POSTV_SIDE_CN} --긍정측면내용 ,DD_DD_OPIN_CN = #{DD_DD_OPIN_CN} --일일소견내용 ,LAST_MDFR_ID = #{LGN_USER_ID} ,LAST_MDFCN_DT = SYSDATE
WHERE SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO} AND CASE_MNG_NO = #{CASE_MNG_NO} AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
AND WRT_YMD = #{WRT_YMD}
AND WRT_YMD = #{WRT_YMD__origin}

mapper.select:

    /* isry.csemd.mdlrtrehabcrsemng.hlngcmp.mapper.HlngCmpMapper.selectDayObservDiaryCheck */
    /* 멘토관찰일지 저장여부 확인 - Lee Sanghoon */

	SELECT
	   COUNT(*)
	FROM AFA260
    WHERE SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
    AND CASE_MNG_NO = #{CASE_MNG_NO}
    AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
